{
  "meta": {
    "name": "Todo App",
    "description": "A simple application to manage personal tasks."
  },
  "entities": [
    {
      "name": "Task",
      "ownable": true,
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true,
          "label": "Title"
        },
        {
          "name": "description",
          "type": "text",
          "label": "Description"
        },
        {
          "name": "dueDate",
          "type": "date",
          "label": "Due Date"
        },
        {
          "name": "completed",
          "type": "boolean",
          "default": false,
          "label": "Completed"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "user",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "user",
      "entity": "Task",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Tasks",
      "route": "/tasks",
      "type": "list",
      "entity": "Task",
      "access": [
        "user"
      ]
    },
    {
      "name": "New Task",
      "route": "/tasks/new",
      "type": "form",
      "entity": "Task",
      "access": [
        "user"
      ]
    },
    {
      "name": "Task Detail",
      "route": "/tasks/:id",
      "type": "detail",
      "entity": "Task",
      "access": [
        "user"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "ownership",
      "id": "taskOwnership",
      "entity": "Task"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
